import * as XLSX from 'xlsx';
import { importLabelFile, exportLabelExcel, exportLabelWord, exportLabelPdf, exportLabelTsc } from './labels.js';
import { importReportFile, exportReportExcel, exportReportWord, exportReportWordPreserve, exportReportPdf } from './reports.js';
import { STUDIES, discoverSites, buildPatients, summarizeAllSites, visitDueState, analyzeImport } from './clinical.js';
import './styles.css';

const BUILTIN_BROWSER_USERS={milana:{name:'Milana',role:'milana',hash:'bdd4dabbc3edc6db40d4404768cccd1465c56e5bfeb56be922283b851c8620d2'},'clinical-ops':{name:'Clinical Ops Staff',role:'staff',hash:'ddee1359279bab58fde766f9c59f2aaf9176823695844b4254407df0ed9917bf'}};
const state={user:null,study:'CL04041383',page:'overview',site:'',sites:[],selectRows:[],visitRows:[],sources:{select:'',visits:''},patients:[],notes:{},localHistory:{},audit:[],db:false,imports:[],snapshotHistory:[],snapshotMeta:null,labels:[],labelSource:'',labelMeta:{layout:'20x40',batch:'890426',mfg:'20.04.2026',exp:'31.03.2029',width:40,height:20,perLabel:1,copies:1,codeMode:'text',from:1,to:''},report:{visit:'6',dates:'18–21.08.2026',site:'',monitor:'',summary:'',source:'',sourceType:'',originalDocx:null,originalFields:null},selected:null,filterProblems:false,search:'',busy:false};
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const fmt=d=>d?new Date(d).toLocaleDateString('ru-RU'):'—',dateKey=d=>d?new Date(d).toISOString().slice(0,10):'';
const activeStudy=()=>STUDIES[state.study]||STUDIES.CL04041383,initials=name=>String(name||'U').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase(),actorInitials=()=>sessionStorage.getItem('clinical_ops_initials')||'';
const noteKey=(site,p,v)=>`${state.study}|${site}|${p}|${v}`,noteForSite=(site,p,v)=>state.notes[noteKey(site,p,v)]||{},noteFor=(p,v)=>noteForSite(state.site,p,v),authToken=()=>sessionStorage.getItem('clinical_ops_auth')||'';
async function authFetch(url,options={}){const headers=new Headers(options.headers||{}),token=authToken(),ini=actorInitials();if(token)headers.set('Authorization',`Basic ${token}`);if(ini)headers.set('X-Actor-Initials',ini);return fetch(url,{...options,headers});}
async function sha256Hex(text){const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text));return [...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('');}
async function builtinLogin(login,password){const rec=BUILTIN_BROWSER_USERS[login];if(!rec)return null;return await sha256Hex(`clinical-ops-v1:${login}:${password}`)===rec.hash?{login,name:rec.name,role:rec.role}:null;}
function saveLocal(){localStorage.setItem('clinical_ops_notes_v2',JSON.stringify(state.notes));localStorage.setItem('clinical_ops_history_v2',JSON.stringify(state.localHistory));localStorage.setItem('clinical_ops_study',state.study);}
function loadLocal(){try{state.notes=JSON.parse(localStorage.getItem('clinical_ops_notes_v2')||'{}');}catch{state.notes={};}try{state.localHistory=JSON.parse(localStorage.getItem('clinical_ops_history_v2')||'{}');}catch{state.localHistory={};}const st=localStorage.getItem('clinical_ops_study');if(st&&STUDIES[st])state.study=st;}
function discover(){state.sites=discoverSites(state.selectRows,state.visitRows);if(!state.sites.includes(state.site))state.site=state.sites[0]||'';}
function derive(){discover();state.patients=buildPatients(state.site,state.selectRows,state.visitRows,noteFor);renderPage();refreshSelectors();}
function allSiteSummaries(){return summarizeAllSites(state.sites,state.selectRows,state.visitRows,noteForSite);}

async function boot(){let user=null;try{const r=await authFetch('/api/auth');if(r.ok){const j=await r.json();if(j.authenticated)user=j.user;}}catch{}state.user=user;if(!user){sessionStorage.removeItem('clinical_ops_auth');renderLogin();return;}loadLocal();renderShell();await loadSnapshotMeta();if(state.db&&state.study==='CL04041383'&&!state.selectRows.length&&!state.visitRows.length)await loadLatestSnapshot(true);await syncWorkspace();}
function renderLogin(){document.body.className='login-page';$('#app').innerHTML=`<main class="login-shell"><section class="login-art"><div class="brand brand-logo"><img src="/brand/clinical-ops-mark.svg" alt="Clinical Ops"><div><strong>Clinical Ops</strong><small>Workspace</small></div></div><div class="login-copy"><div class="eyebrow">CLINICAL OPERATIONS · 2026</div><h1>Workflows without<br><span>spreadsheet archaeology.</span></h1><p>Visits, regimens, deviations, labels, reports and shared source snapshots in one operational workspace.</p></div><div class="trust"><span>Controlled imports</span><span>Mobile-ready</span><span>Milana AI layer</span></div></section><section class="login-panel"><form id="loginForm" class="login-card" novalidate><div class="kicker">SECURE WORKSPACE</div><h2>Sign in</h2><p>Staff does daily operational work. Milana gets the same workspace plus operator/AI controls.</p><label>Login<input name="login" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><label>Staff initials <small>(optional, used in audit)</small><input name="initials" maxlength="12" placeholder="MS"></label><button id="loginButton" type="submit" class="btn primary wide">Enter workspace</button><div id="loginError" class="login-error" role="alert"></div></form></section></main>`;const form=$('#loginForm'),button=$('#loginButton'),error=$('#loginError');form.addEventListener('submit',async e=>{e.preventDefault();if(state.busy)return;const fd=new FormData(form),login=String(fd.get('login')||'').trim(),password=String(fd.get('password')||''),ini=String(fd.get('initials')||'').trim();if(!login||!password){error.textContent='Enter login and password.';return;}state.busy=true;button.disabled=true;button.textContent='Signing in…';error.textContent='';try{let user=null;try{const c=new AbortController(),timer=setTimeout(()=>c.abort(),7000),r=await fetch('/api/auth?action=login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({login,password}),signal:c.signal});clearTimeout(timer);const text=await r.text();let j={};try{j=text?JSON.parse(text):{};}catch{}if(r.ok&&j.user)user=j.user;else if(r.status===401){error.textContent=j.error||'Invalid login or password';return;}}catch{}if(!user)user=await builtinLogin(login,password);if(!user){error.textContent='Could not sign in. Check credentials or hosting configuration.';return;}sessionStorage.setItem('clinical_ops_auth',btoa(`${login}:${password}`));if(ini)sessionStorage.setItem('clinical_ops_initials',ini);else sessionStorage.removeItem('clinical_ops_initials');state.user=user;loadLocal();renderShell();await loadSnapshotMeta();if(state.db&&state.study==='CL04041383'&&!state.selectRows.length&&!state.visitRows.length)await loadLatestSnapshot(true);await syncWorkspace();}catch(err){console.error(err);error.textContent='Login failed unexpectedly.';}finally{state.busy=false;const b=$('#loginButton');if(b){b.disabled=false;b.textContent='Enter workspace';}}});}

function studyOptions(){return Object.values(STUDIES).map(s=>`<option value="${s.code}" ${s.code===state.study?'selected':''}>${s.code} · ${esc(s.name)}</option>`).join('');}
function siteOptions(){if(!state.sites.length)return '<option value="">No sites loaded</option>';return state.sites.map(s=>`<option value="${esc(s)}" ${s===state.site?'selected':''}>Site ${esc(s)}</option>`).join('');}
function nav(page,label,icon){return `<button class="nav-item ${state.page===page?'active':''}" data-page="${page}"><span>${icon}</span>${label}</button>`;}
function allowed(page){return activeStudy().modules.includes(page)||page==='data'||(page==='ai'&&state.user?.role==='milana');}
function renderShell(){discover();document.body.className=`role-${state.user.role}`;$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand side brand-logo"><img src="/brand/clinical-ops-mark.svg" alt=""><div><strong>Clinical Ops</strong><small>${esc(state.study)}</small></div></div><nav>${nav('overview','Overview','⌂')}${nav('patients','Patients','◎')}${nav('actions','Action Center','!')}${nav('labels','Labels','▣')}${nav('reports','Reports','▤')}${nav('data','Import Center','⇅')}${state.user.role==='milana'?'<div class="nav-rule"></div>'+nav('ai','Semyon AI','✦'):''}</nav><div class="sidebar-foot"><div class="privacy"><i></i><div><strong>${state.db?'Shared workspace':'Local workspace'}</strong><span>${state.db?'Snapshots + notes can sync':'Source files stay in this browser'}</span></div></div></div></aside><section class="workspace"><header class="topbar"><div class="top-selectors"><select id="studySel" class="study-select">${studyOptions()}</select><select id="siteSel" ${state.study!=='CL04041383'||!state.sites.length?'disabled':''}>${siteOptions()}</select></div><div class="top-actions"><button id="importBtn" class="btn ghost">Import data</button><div class="user"><span>${esc(initials(state.user.name))}</span><div><strong>${esc(state.user.name)}${actorInitials()?` · ${esc(actorInitials())}`:''}</strong><small>${state.user.role==='milana'?'Admin · AI enabled':'Staff'}</small></div></div><button id="logoutBtn" class="icon-btn" title="Sign out">↗</button></div></header><main id="view"></main></section></div><input id="filePicker" type="file" multiple accept=".xlsx,.xls" hidden><input id="labelFilePicker" type="file" multiple accept=".xlsx,.xls,.docx" hidden><input id="reportFilePicker" type="file" accept=".xlsx,.xls,.docx" hidden>`;$$('.nav-item').forEach(b=>b.onclick=()=>{state.page=allowed(b.dataset.page)?b.dataset.page:(state.study==='CL04041109'?'labels':'overview');renderPage();});$('#studySel').onchange=e=>switchStudy(e.target.value);$('#siteSel').onchange=e=>{state.site=e.target.value;derive();syncWorkspace();};$('#importBtn').onclick=()=>{state.page='data';renderPage();setTimeout(()=>$('#filePicker')?.click(),0);};$('#filePicker').onchange=e=>stageImports([...e.target.files]);$('#labelFilePicker').onchange=e=>importLabelFiles([...e.target.files]);$('#reportFilePicker').onchange=e=>importReportFiles([...e.target.files]);$('#logoutBtn').onclick=logout;renderPage();}
function refreshSelectors(){const ss=$('#siteSel');if(ss){ss.innerHTML=siteOptions();ss.disabled=state.study!=='CL04041383'||!state.sites.length;if(state.site)ss.value=state.site;}const st=$('#studySel');if(st)st.value=state.study;}
async function switchStudy(code){if(!STUDIES[code])return;state.study=code;saveLocal();if(!allowed(state.page))state.page=code==='CL04041109'?'labels':'overview';state.selected=null;renderShell();await loadSnapshotMeta();if(state.db&&state.study==='CL04041383'&&!state.selectRows.length&&!state.visitRows.length)await loadLatestSnapshot(true);await syncWorkspace();}
function logout(){sessionStorage.removeItem('clinical_ops_auth');sessionStorage.removeItem('clinical_ops_initials');state.user=null;renderLogin();}

function pageHead(kicker,title,sub,actions=''){return `<div class="page-head"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${sub}</p></div><div class="page-actions">${actions}</div></div>`;}
function metric(n,label,sub,t=''){return `<div class="metric ${t}"><strong>${n}</strong><span>${label}</span><small>${sub}</small></div>`;}
function renderPage(){const v=$('#view');if(!v)return;if(!allowed(state.page))state.page=state.study==='CL04041109'?'labels':'overview';const map={overview,patients,actions,labels,reports,data,ai};v.innerHTML=(map[state.page]||overview)();bindPage();}
function overview(){if(state.study==='CL04041109')return labelOverview();const p=state.patients,all=allSiteSummaries();return `${pageHead('STUDY WORKSPACE',`${state.study} · ${activeStudy().name}`,'All sites first; drill into a site only when you need patient-level detail.','<button class="btn primary" data-goto="actions">Open action center</button>')}<section class="quick-actions"><button data-goto="actions"><b>!</b><span>Issues</span></button><button data-filter-due><b>◷</b><span>Due soon</span></button><button data-goto="data"><b>⇅</b><span>Import</span></button><button data-goto="patients"><b>⌕</b><span>Patients</span></button></section><section class="metrics">${metric(all.reduce((a,x)=>a+x.patients,0),'Patients','all loaded sites')}${metric(all.reduce((a,x)=>a+x.exceptions,0),'Window exceptions','all sites','danger')}${metric(all.reduce((a,x)=>a+x.dueSoon,0),'Due ≤7 days','across study','warn')}${metric(all.reduce((a,x)=>a+x.overdue,0),'Overdue','missing actual visit','danger')}</section><section class="grid"><div class="card"><div class="card-head"><div><span class="eyebrow">ALL SITES</span><h2>Operational status</h2></div><span class="muted">${all.length} sites</span></div><div class="site-grid">${all.map(siteCard).join('')||empty('Import source files to discover sites.')}</div></div></section>${state.site?`<section class="grid two"><div class="card"><div class="card-head"><div><span class="eyebrow">SITE ${esc(state.site)}</span><h2>Priority queue</h2></div><button class="link" data-goto="actions">View all →</button></div>${queue(6)}</div><div class="card"><div class="card-head"><div><span class="eyebrow">REGIMEN</span><h2>Week 22 / Week 40</h2></div></div><div class="change-list">${p.slice(0,8).map(changeRow).join('')||empty('No patients for this site.')}</div></div></section>`:''}`;}
function labelOverview(){return `${pageHead('LABEL WORKSPACE',`${state.study} · ${activeStudy().name}`,'Medication-label workflow is separated from the visit-tracking study.','<button class="btn primary" data-goto="labels">Open Label Studio</button>')}<section class="metrics">${metric(state.labels.length,'Label IDs','currently loaded')}${metric(state.labelMeta.layout,'Layout','current output')}${metric(state.labelMeta.batch||'—','Batch','current label job')}${metric(state.labelSource?'1':'0','Sources',state.labelSource||'none')}</section><section class="grid two"><div class="card"><h2>Label Studio</h2><p class="muted">Import Word or Excel, preview, then export Word, Excel, PDF, direct TSC/TSPL or print.</p><button class="btn primary" data-goto="labels">Create labels</button></div><div class="card"><h2>Protocol-aware workspace</h2><p class="muted">Future studies can be added without hardcoding the entire platform around one site or one protocol.</p></div></section>`;}
function siteCard(s){const tone=s.overdue||s.exceptions?'bad':s.dueSoon?'warn':'good';return `<button class="site-card" data-site="${esc(s.site)}"><div><span class="eyebrow">SITE</span><strong>${esc(s.site)}</strong></div><div class="site-stats"><span><b>${s.patients}</b> patients</span><span class="${s.exceptions?'bad-text':''}"><b>${s.exceptions}</b> exceptions</span><span><b>${s.dueSoon}</b> due</span><span class="${s.overdue?'bad-text':''}"><b>${s.overdue}</b> overdue</span></div><i class="site-health ${tone}"></i></button>`;}
function patients(){let rows=state.patients.filter(p=>!state.search||p.id.toLowerCase().includes(state.search.toLowerCase()));if(state.filterProblems)rows=rows.filter(p=>p.violations||p.visits.some(v=>v.changed||visitDueState(v)));return `${pageHead('PATIENT WORKSPACE',`Patients · Site ${state.site||'—'}`,'Review visits, regimen changes, deviations, version history and working corrections.','<button class="btn ghost" id="exportPatients">Export CSV</button>')}<div class="toolbar"><input id="patientSearch" placeholder="Search patient…" value="${esc(state.search)}"><label class="switch"><input id="problemOnly" type="checkbox" ${state.filterProblems?'checked':''}><span></span>Problems / due only</label></div><section class="card flush">${patientTable(rows,true)}</section>${state.selected?patientDrawer(state.selected):''}`;}
function patientTable(rows,clickable=false){return `<div class="table-wrap"><table><thead><tr><th>Patient</th><th>Baseline</th><th>Status</th><th>Week 22</th><th>W22 regimen</th><th>Week 40</th><th>W40 regimen</th><th>Exceptions</th></tr></thead><tbody>${rows.map(p=>`<tr ${clickable?`data-patient="${p.id}" class="clickable"`:''}><td><strong>${p.id}</strong></td><td>${p.baseline??'—'}</td><td><span class="status neutral">${esc(p.status||'Unknown')}</span></td><td>${fmt(p.visits[5]?.actual)}</td><td>${regChange(p.visits[5])}</td><td>${fmt(p.visits[8]?.actual)}</td><td>${regChange(p.visits[8])}</td><td><span class="status ${p.violations?'bad':'good'}">${p.violations}</span></td></tr>`).join('')||`<tr><td colspan="8">${empty('No patients to display.')}</td></tr>`}</tbody></table></div>`;}
function regChange(v){if(!v)return'—';return v.changed?`<span class="reg-change">${esc(v.before||'—')} → ${esc(v.regimen||'—')}</span>`:`<span>${esc(v.regimen||'—')}</span>`;}
function patientDrawer(id){const p=state.patients.find(x=>x.id===id);if(!p)return'';return `<div class="drawer-backdrop" data-close-drawer></div><aside class="drawer"><div class="drawer-head"><div><span class="eyebrow">PATIENT</span><h2>${esc(id)}</h2><p>Site ${esc(state.site)} · Baseline ${p.baseline??'—'} · ${esc(p.status||'Unknown')}</p></div><button class="icon-btn" data-close-drawer>×</button></div><div class="timeline">${p.visits.map(v=>visitCard(p,v)).join('')}</div></aside>`;}
function visitCard(p,v){const n=noteFor(p.id,v.no),due=visitDueState(v),needsDeviation=['Early','Late'].includes(v.window),ref=`${p.id}|${v.no}`;return `<article class="visit ${v.no===6||v.no===9?'key':''}"><div class="visit-dot"></div><div class="visit-body"><div class="visit-title"><div><strong>Visit ${v.no} · Week ${v.week}</strong><span>Day ${v.day}${due?` · ${esc(due.label)}`:''}</span></div>${status(v.window,due)}</div><div class="visit-grid"><span>Actual<b>${fmt(v.actual)}</b></span><span>Window<b>${fmt(v.min)} – ${fmt(v.max)}</b></span><span>Regimen<b>${esc(v.before||'—')}${v.changed?` → ${esc(v.regimen||'—')}`:''}</b></span></div><div class="deviation-box ${needsDeviation?'needs-deviation':''}"><div class="deviation-grid"><label>Deviation No.<input data-devno="${ref}" value="${esc(n.deviationNo||'')}" placeholder="e.g. PD-104"></label><label>Status<select data-devstatus="${ref}"><option value="" ${!n.deviationStatus?'selected':''}>Not set</option><option value="open" ${n.deviationStatus==='open'?'selected':''}>Open</option><option value="resolved" ${n.deviationStatus==='resolved'?'selected':''}>Resolved</option></select></label><label>Owner<input data-devowner="${ref}" value="${esc(n.deviationOwner||'')}" placeholder="Initials / name"></label><label class="wide">Reason<input data-devreason="${ref}" value="${esc(n.deviationReason||'')}" placeholder="Reason / classification"></label></div><textarea data-note="${ref}" placeholder="Working note / follow-up…">${esc(n.note||'')}</textarea><div class="override-row version-actions"><input type="date" data-odate="${ref}" value="${esc(n.overrideDate||'')}"><select data-oreg="${ref}"><option value="">No regimen override</option>${['E2W','E4W','E8W'].map(r=>`<option ${n.overrideRegimen===r?'selected':''}>${r}</option>`).join('')}</select><button class="btn small" data-history="${ref}">History</button><button class="btn small" data-undo="${ref}">Undo</button><button class="btn small primary" data-save="${ref}">Save</button></div><div class="version-panel" data-history-panel="${ref}"></div>${n.updatedBy?`<small class="edited-by">Last edited by ${esc(n.updatedBy)}</small>`:''}</div></div></article>`;}
function status(w,due){if(due){const c=due.kind==='overdue'?'bad':due.kind==='due'?'warn':'neutral';return `<span class="status ${c}">${esc(due.label)}</span>`;}return `<span class="status ${w==='Within'?'good':w==='Pending'?'neutral':'bad'}">${w}</span>`;}
function actions(){return `${pageHead('ACTION CENTER','What needs attention','Window exceptions, incomplete deviations, due visits and regimen changes.','<button class="btn ghost" id="exportActions">Export CSV</button>')}<section class="card"><div class="action-list">${queue(999)}</div></section>`;}
function actionItems(){const items=[];state.patients.forEach(p=>p.visits.forEach(v=>{const n=noteFor(p.id,v.no),due=visitDueState(v);if(['Early','Late'].includes(v.window)){items.push({tone:'red',title:`${p.id} · Visit ${v.no}`,sub:`${v.window} · ${fmt(v.actual)} outside ${fmt(v.min)}–${fmt(v.max)}`,p:p.id});if(!n.deviationNo||!n.deviationReason)items.push({tone:'amber',title:`${p.id} · Visit ${v.no}`,sub:'Deviation record incomplete · add number and reason',p:p.id});}if(due)items.push({tone:due.kind==='overdue'?'red':'amber',title:`${p.id} · Visit ${v.no}`,sub:due.label,p:p.id});if((v.no===6||v.no===9)&&v.changed)items.push({tone:'blue',title:`${p.id} · Week ${v.week}`,sub:`Regimen changed ${v.before||'—'} → ${v.regimen||'—'}`,p:p.id});}));return items;}
function queue(limit){return actionItems().slice(0,limit).map(x=>`<button class="action-item" data-open-patient="${x.p}"><i class="${x.tone}"></i><div><strong>${esc(x.title)}</strong><span>${esc(x.sub)}</span></div><b>→</b></button>`).join('')||empty('No current exceptions or due items.')}
function changeRow(p){return `<button class="change-row" data-open-patient="${p.id}"><strong>${p.id}</strong><span>W22 ${regChange(p.visits[5])}</span><span>W40 ${regChange(p.visits[8])}</span></button>`;}

function standardLayout(layout){return layout==='80x60'?{width:80,height:60,perLabel:10}:layout==='20x40'?{width:40,height:20,perLabel:1}:null;}
function labels(){const m=state.labelMeta,custom=m.layout==='custom';return `${pageHead('LABEL STUDIO','Labels','Import Word/Excel; output Word, Excel, PDF, Print or direct TSC/TSPL.','<button class="btn ghost" id="loadLabels">Import Word / Excel</button>')}<section class="grid label-grid"><div class="card"><div class="form-grid label-advanced"><label>Layout<select id="labelLayout"><option value="20x40" ${m.layout==='20x40'?'selected':''}>20×40 mm · one ID</option><option value="80x60" ${m.layout==='80x60'?'selected':''}>80×60 mm · 10 IDs</option><option value="custom" ${custom?'selected':''}>Custom</option></select></label><label>Batch<input id="batch" value="${esc(m.batch)}"></label><label>Manufactured<input id="mfg" value="${esc(m.mfg)}"></label><label>Expiry<input id="exp" value="${esc(m.exp)}"></label><label>Width mm<input id="labelWidth" type="number" min="20" max="150" value="${m.width}" ${custom?'':'disabled'}></label><label>Height mm<input id="labelHeight" type="number" min="15" max="100" value="${m.height}" ${custom?'':'disabled'}></label><label>IDs / label<input id="labelPer" type="number" min="1" max="30" value="${m.perLabel}" ${custom?'':'disabled'}></label><label>Copies<input id="labelCopies" type="number" min="1" max="20" value="${m.copies}"></label><label>From item<input id="labelFrom" type="number" min="1" value="${m.from||1}"></label><label>To item<input id="labelTo" type="number" min="1" placeholder="all" value="${esc(m.to||'')}"></label><label>Printer code<select id="labelCodeMode"><option value="text" ${m.codeMode==='text'?'selected':''}>Text</option><option value="code128" ${m.codeMode==='code128'?'selected':''}>Code 128</option><option value="qr" ${m.codeMode==='qr'?'selected':''}>QR</option></select></label></div><div class="label-source"><strong>${state.labelSource?esc(state.labelSource):'No label source loaded'}</strong><span>${state.labels.length?`${state.labels.length} IDs recognized`:'Import .docx, .xlsx or .xls'}</span></div><div class="label-actions label-export-actions"><button class="btn" id="labelExportWord">Word .docx</button><button class="btn" id="labelExportExcel">Excel .xlsx</button><button class="btn primary" id="labelExportPdf">PDF</button><button class="btn" id="labelExportTsc">TSC / TSPL</button><button class="btn ghost" id="printLabels">Print</button></div><div id="labelExportStatus" class="label-export-status"></div></div><div class="card preview-card"><div class="card-head"><h2>Live preview</h2></div><div id="labelPreview">${labelPreview()}</div></div></section>`;}
function updateLabelMeta(){let layout=$('#labelLayout')?.value||state.labelMeta.layout;const standard=standardLayout(layout);state.labelMeta={...state.labelMeta,layout,batch:$('#batch')?.value||'',mfg:$('#mfg')?.value||'',exp:$('#exp')?.value||'',width:standard?.width??Number($('#labelWidth')?.value||state.labelMeta.width),height:standard?.height??Number($('#labelHeight')?.value||state.labelMeta.height),perLabel:standard?.perLabel??Number($('#labelPer')?.value||state.labelMeta.perLabel),copies:Number($('#labelCopies')?.value||1),from:Number($('#labelFrom')?.value||1),to:$('#labelTo')?.value||'',codeMode:$('#labelCodeMode')?.value||'text'};const p=$('#labelPreview');if(p)p.innerHTML=labelPreview();}
function labelJob(){const m=state.labelMeta,from=Math.max(1,Number(m.from)||1),to=m.to?Math.min(state.labels.length,Number(m.to)||state.labels.length):state.labels.length;return {layout:m.layout,batch:m.batch,mfg:m.mfg,exp:m.exp,width:m.width,height:m.height,perLabel:m.perLabel,copies:m.copies,codeMode:m.codeMode,ids:state.labels.slice(from-1,to)};}
function labelPreview(){const j=labelJob();if(!j.ids.length)return empty('Import a Word or Excel label list to preview.');const ids=j.ids.slice(0,Math.max(1,j.perLabel||1));return `<div class="label-paper"><div class="label-top"><strong>CL04041109 · Placebo</strong><span>Batch ${esc(j.batch)} · ${j.width}×${j.height} mm</span></div><div class="label-id">${ids.map(x=>`<b>${esc(x)}</b>`).join('')}</div><small>Только для клинических исследований</small></div>`;}
async function runLabelExport(fn){const status=$('#labelExportStatus');try{updateLabelMeta();const job=labelJob();if(!job.ids.length)throw new Error('Import a Word or Excel label list first.');if(status)status.textContent='Preparing file…';await fn(job);if(status)status.textContent='Export ready.';}catch(err){console.error(err);if(status)status.textContent=err?.message||'Export failed.';}}

function reports(){const r=state.report,site=r.site||state.site||'',hasOriginal=Boolean(r.originalDocx);return `${pageHead('REPORT STUDIO','Reports','Upload Word/Excel, edit recognized content, then save Word, Excel, PDF or print.','<button class="btn primary" id="loadReport">Upload Word / Excel</button>')}<section class="grid two report-grid"><div class="card"><div class="report-source"><strong>${r.source?esc(r.source):'No report source loaded'}</strong><span>${r.source?`${esc(r.sourceType||'Document')} imported · editable working copy`:'Start from scratch or import .docx, .xlsx or .xls'}</span></div><div class="form-grid report"><label>Visit / IMV number<input id="rVisit" value="${esc(r.visit||'')}"></label><label>Visit dates<input id="rDates" value="${esc(r.dates||'')}"></label><label>Site<input id="rSite" value="${esc(site)}"></label><label>Monitor<input id="rMon" value="${esc(r.monitor||'')}" placeholder="Name"></label><label class="wide">Report content / summary<textarea id="rSummary" rows="14" placeholder="Monitoring findings, documents, deviations, follow-up…">${esc(r.summary||'')}</textarea></label></div><div class="report-actions"><button class="btn" id="reportExportWord">Word · normalized</button>${hasOriginal?'<button class="btn" id="reportPreserveWord">Word · preserve original</button>':''}<button class="btn" id="reportExportExcel">Excel .xlsx</button><button class="btn primary" id="reportExportPdf">PDF</button><button class="btn ghost" id="printReport">Print</button></div><div id="reportExportStatus" class="label-export-status">${hasOriginal?'Preserve-original mode keeps the imported DOCX package and updates recognized fields where possible; a working update page is appended for traceability.':''}</div></div><div class="card report-preview" id="reportPreview">${reportPreview()}</div></section>`;}
function reportJob(){const r=state.report;return {visit:r.visit||'',dates:r.dates||'',site:r.site||state.site||'',monitor:r.monitor||'',summary:r.summary||'',source:r.source||'',originalDocx:r.originalDocx||null,originalFields:r.originalFields||null};}
function reportPreview(){const r=reportJob();return `<span class="eyebrow">LIVE PREVIEW</span><h2>Interim Monitoring Visit</h2><p>Protocol CL04041383 · Site ${esc(r.site||'—')}</p><hr><h3>Visit details</h3><p><b>IMV #${esc(r.visit||'—')}</b> · ${esc(r.dates||'Dates not entered')}</p><p>Monitor: ${esc(r.monitor||'—')}</p><h3>Report content</h3><div class="report-preview-text">${r.summary?esc(r.summary).replace(/\n/g,'<br>'):'<span class="muted">Import a Word/Excel report or enter content on the left.</span>'}</div>`;}
function updateReportState(){state.report={...state.report,visit:$('#rVisit')?.value||'',dates:$('#rDates')?.value||'',site:$('#rSite')?.value||'',monitor:$('#rMon')?.value||'',summary:$('#rSummary')?.value||''};const p=$('#reportPreview');if(p)p.innerHTML=reportPreview();}
async function runReportExport(fn){const status=$('#reportExportStatus');try{updateReportState();if(status)status.textContent='Preparing file…';const result=await fn(reportJob());if(status)status.textContent=result?.changes!=null?`Preserved original DOCX · ${result.changes} recognized field nodes updated · working update appended.`:'Export ready.';}catch(err){console.error(err);if(status)status.textContent=err?.message||'Export failed.';}}

function data(){const pending=state.imports.filter(x=>!x.applied);return `${pageHead('IMPORT CENTER','Source data','Inspect what was recognized before source data changes the workspace.','<button class="btn primary" id="dataImport">Choose Excel files</button>')}<section class="grid source-summary"><div class="card source-card"><span class="source-icon">S</span><div><strong>SelectControls</strong><p>Dosing regimen and patient status.</p><span class="source-state ${state.selectRows.length?'ok':''}">${state.selectRows.length?`${state.selectRows.length} rows · ${esc(state.sources.select||'source loaded')}`:'Not loaded'}</span></div></div><div class="card source-card"><span class="source-icon">V</span><div><strong>Visits completion</strong><p>Scheduled min/max and Actual visit date.</p><span class="source-state ${state.visitRows.length?'ok':''}">${state.visitRows.length?`${state.visitRows.length} rows · ${esc(state.sources.visits||'source loaded')}`:'Not loaded'}</span></div></div></section>${pending.length?`<section class="grid"><div class="card"><div class="card-head"><div><span class="eyebrow">STAGED</span><h2>Review before applying</h2></div><button class="btn primary" id="applyAllImports">Apply recognized</button></div><div class="import-list">${pending.map(importCard).join('')}</div></div></section>`:''}<section class="grid two"><div class="card"><div class="card-head"><div><span class="eyebrow">SHARED SNAPSHOT</span><h2>Same dataset on phone and desktop</h2></div></div><p class="muted">Publishing is explicit: original files are parsed locally; only processed rows are stored in the shared workspace database.</p><div class="snapshot-actions"><button class="btn primary" id="publishSnapshot" ${state.db?'':'disabled'}>Publish current snapshot</button><button class="btn" id="loadSnapshot" ${state.db?'':'disabled'}>Load latest shared snapshot</button></div><div id="snapshotStatus" class="label-export-status">${state.db?(state.snapshotMeta?`Latest: ${fmt(state.snapshotMeta.created_at)} · ${esc(state.snapshotMeta.actor||'')}`:'No shared snapshot yet'):'Shared snapshot requires DATABASE_URL on the deployment.'}</div></div><div class="card"><div class="card-head"><div><span class="eyebrow">IMPORT RULES</span><h2>Recognition checks</h2></div></div><p class="muted">SelectControls is recognized by Randomization / DISP_REGIMEN fields. Visits completion is recognized by Activity plus scheduling/actual-date columns. Unknown files stay staged instead of silently changing data.</p><div class="health">Discovered sites: <strong>${state.sites.length}</strong> · Study: <strong>${esc(state.study)}</strong></div></div></section>`;}
function importCard(x){const cols=x.columns.slice(0,8).join(', ');return `<div class="import-card"><div class="import-main"><strong>${esc(x.name)}</strong><span>${x.rows.length} rows · ${x.sites.length} sites · ${x.subjects} subjects</span><small>${esc(cols)}${x.columns.length>8?'…':''}</small>${x.warnings.length?`<div class="import-warnings">${x.warnings.map(w=>`<span>${esc(w)}</span>`).join('')}</div>`:''}</div><div class="import-controls"><select data-import-kind="${x.id}"><option value="select" ${x.kind==='select'?'selected':''}>SelectControls</option><option value="visits" ${x.kind==='visits'?'selected':''}>Visits completion</option><option value="unknown" ${x.kind==='unknown'?'selected':''}>Unknown / ignore</option></select><button class="btn small primary" data-apply-import="${x.id}" ${x.kind==='unknown'?'disabled':''}>Apply</button></div></div>`;}

function ai(){if(state.user.role!=='milana')return overview();const diag=diagnostics();return `${pageHead('MILANA · ADMIN','Semyon AI Operator','Scoped operator layer over shared Clinical Ops data.','<span class="ai-pill">✦ Milana only</span>')}<section class="grid ai-grid"><div class="card"><div class="ai-context"><span>Study <b>${esc(state.study)}</b></span><span>Sites <b>${state.sites.length}</b></span><span>Patients <b>${state.patients.length}</b></span><span>DB <b>${state.db?'shared':'local'}</b></span></div><textarea id="aiPrompt" class="ai-prompt" placeholder="Например: проверь все сайты и покажи отклонения без номера…"></textarea><div class="chips"><button data-ai="Проверь все нарушения окон визитов и выдели те, где нет номера или причины deviation.">Deviation review</button><button data-ai="Покажи все upcoming и overdue визиты по всем сайтам.">Due review</button><button data-ai="Сравни Week 22 и Week 40 regimen changes.">Regimen review</button></div><div class="ai-buttons"><button class="btn" id="runDiagnostics">Local diagnostics</button><button class="btn" id="runLiveOperator" ${state.db?'':'disabled'}>Shared live check</button><button class="btn primary" id="prepareAi">Prepare task packet</button></div><pre id="aiPacket" class="ai-packet">${esc(diag.join('\n'))}</pre></div><div class="card"><span class="eyebrow">SCOPED TOOLS</span><h2>Safe operator model</h2><div class="manual"><p><b>Read:</b> study/site summary, patient, action queue and operator rules.</p><p><b>Write:</b> Milana-only audited notes, deviations and working overrides via `/api/operator`.</p><p><b>No:</b> unrestricted SQL or shell access.</p><p><b>Source:</b> imported exports remain source-of-truth; shared snapshots are explicit published copies.</p></div></div></section>${auditView()}`;}
function diagnostics(){const all=allSiteSummaries(),incomplete=[];all.forEach(s=>s.patientRows.forEach(p=>p.visits.forEach(v=>{if(['Early','Late'].includes(v.window)){const n=noteForSite(s.site,p.id,v.no);if(!n.deviationNo||!n.deviationReason)incomplete.push(`${s.site} · ${p.id} · V${v.no}`);}})));return [`Study ${state.study}`,`${all.length} sites · ${all.reduce((a,x)=>a+x.patients,0)} patients`,`${all.reduce((a,x)=>a+x.exceptions,0)} window exceptions`,`${all.reduce((a,x)=>a+x.dueSoon,0)} due within 7 days`,`${all.reduce((a,x)=>a+x.overdue,0)} overdue visits`,`${incomplete.length} deviations missing number/reason`,...incomplete.slice(0,20).map(x=>`- ${x}`)];}
function auditView(){return `<section class="card"><div class="card-head"><h2>Audit trail</h2></div><div class="audit-list">${state.audit.map(a=>`<div><span>${fmt(a.created_at)}</span><strong>${esc(a.actor||'—')}</strong><p>${esc(a.action||'Update')} · ${esc(a.detail||'')}</p></div>`).join('')||empty('Shared audit appears here when DATABASE_URL is configured.')}</div></section>`;}

function bindPage(){$$('[data-goto]').forEach(x=>x.onclick=()=>{state.page=x.dataset.goto;renderPage();});$$('[data-site]').forEach(x=>x.onclick=async()=>{state.site=x.dataset.site;derive();await syncWorkspace();});$$('[data-open-patient]').forEach(x=>x.onclick=()=>{state.selected=x.dataset.openPatient;state.page='patients';renderPage();});$$('tr[data-patient]').forEach(x=>x.onclick=()=>{state.selected=x.dataset.patient;renderPage();});$$('[data-close-drawer]').forEach(x=>x.onclick=()=>{state.selected=null;renderPage();});const ps=$('#patientSearch');if(ps)ps.oninput=e=>{state.search=e.target.value;renderPage();};const po=$('#problemOnly');if(po)po.onchange=e=>{state.filterProblems=e.target.checked;renderPage();};$('[data-filter-due]')?.addEventListener('click',()=>{state.filterProblems=true;state.page='patients';renderPage();});$('#exportPatients')?.addEventListener('click',()=>exportCSV('patients.csv',patientCsv()));$('#exportActions')?.addEventListener('click',()=>exportCSV('actions.csv',actionCsv()));$$('[data-save]').forEach(b=>b.onclick=()=>saveNote(b.dataset.save));$$('[data-undo]').forEach(b=>b.onclick=()=>undoNote(b.dataset.undo));$$('[data-history]').forEach(b=>b.onclick=()=>showHistory(b.dataset.history));$('#loadLabels')?.addEventListener('click',()=>$('#labelFilePicker').click());['batch','mfg','exp','labelWidth','labelHeight','labelPer','labelCopies','labelFrom','labelTo','labelCodeMode'].forEach(id=>$('#'+id)?.addEventListener('input',updateLabelMeta));$('#labelLayout')?.addEventListener('change',()=>{const v=$('#labelLayout').value,s=standardLayout(v);if(s){state.labelMeta={...state.labelMeta,layout:v,...s};}else state.labelMeta.layout=v;renderPage();});$('#labelExportWord')?.addEventListener('click',()=>runLabelExport(exportLabelWord));$('#labelExportExcel')?.addEventListener('click',()=>runLabelExport(exportLabelExcel));$('#labelExportPdf')?.addEventListener('click',()=>runLabelExport(exportLabelPdf));$('#labelExportTsc')?.addEventListener('click',()=>runLabelExport(exportLabelTsc));$('#printLabels')?.addEventListener('click',()=>{updateLabelMeta();printLabels();});$('#loadReport')?.addEventListener('click',()=>$('#reportFilePicker').click());['rVisit','rDates','rSite','rMon','rSummary'].forEach(id=>$('#'+id)?.addEventListener('input',updateReportState));$('#reportExportWord')?.addEventListener('click',()=>runReportExport(exportReportWord));$('#reportPreserveWord')?.addEventListener('click',()=>runReportExport(exportReportWordPreserve));$('#reportExportExcel')?.addEventListener('click',()=>runReportExport(exportReportExcel));$('#reportExportPdf')?.addEventListener('click',()=>runReportExport(exportReportPdf));$('#printReport')?.addEventListener('click',()=>{updateReportState();printReport();});$('#dataImport')?.addEventListener('click',()=>$('#filePicker').click());$$('[data-import-kind]').forEach(s=>s.onchange=()=>{const x=state.imports.find(i=>i.id===s.dataset.importKind);if(x){x.kind=s.value;renderPage();}});$$('[data-apply-import]').forEach(b=>b.onclick=()=>applyImport(b.dataset.applyImport));$('#applyAllImports')?.addEventListener('click',applyAllImports);$('#publishSnapshot')?.addEventListener('click',publishSnapshot);$('#loadSnapshot')?.addEventListener('click',()=>loadLatestSnapshot(true));$$('[data-ai]').forEach(b=>b.onclick=()=>{$('#aiPrompt').value=b.dataset.ai;});$('#runDiagnostics')?.addEventListener('click',()=>{$('#aiPacket').textContent=diagnostics().join('\n');});$('#runLiveOperator')?.addEventListener('click',runLiveOperator);$('#prepareAi')?.addEventListener('click',prepareAi);}

async function stageImports(files){if(!files.length)return;state.page='data';for(const file of files){try{state.imports.push(analyzeImport(file.name,await readWorkbook(file)));}catch(err){state.imports.push({id:`err_${Date.now()}_${Math.random()}`,name:file.name,kind:'unknown',rows:[],columns:[],sites:[],subjects:0,warnings:[err?.message||'Could not parse file']});}}const p=$('#filePicker');if(p)p.value='';renderPage();}
async function readWorkbook(file){const buf=await file.arrayBuffer(),wb=XLSX.read(buf,{type:'array',cellDates:true});let ws=null;for(const name of wb.SheetNames){if(wb.Sheets[name]?.['!ref']){ws=wb.Sheets[name];break;}}return ws?XLSX.utils.sheet_to_json(ws,{defval:null,raw:false,dateNF:'yyyy-mm-dd'}):[];}
function applyImport(id){const x=state.imports.find(i=>i.id===id);if(!x||x.kind==='unknown')return;if(x.kind==='select'){state.selectRows=x.rows;state.sources.select=x.name;}if(x.kind==='visits'){state.visitRows=x.rows;state.sources.visits=x.name;}x.applied=true;discover();derive();saveLocal();renderPage();}
function applyAllImports(){state.imports.filter(x=>!x.applied&&x.kind!=='unknown').forEach(x=>{if(x.kind==='select'){state.selectRows=x.rows;state.sources.select=x.name;}if(x.kind==='visits'){state.visitRows=x.rows;state.sources.visits=x.name;}x.applied=true;});discover();derive();renderPage();}
async function publishSnapshot(){const s=$('#snapshotStatus');try{if(!state.db)throw new Error('Shared database is not configured.');if(s)s.textContent='Publishing…';const r=await authFetch('/api/snapshot',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({study:state.study,snapshot:{selectRows:state.selectRows,visitRows:state.visitRows,sources:state.sources}})}),j=await r.json();if(!r.ok)throw new Error(j.error||'Publish failed');if(s)s.textContent=`Published ${fmt(j.created_at)}.`;await loadSnapshotMeta();}catch(err){if(s)s.textContent=err?.message||'Publish failed.';}}
async function loadSnapshotMeta(){try{const r=await authFetch(`/api/snapshot?study=${encodeURIComponent(state.study)}`);if(!r.ok)return;const j=await r.json();state.db=Boolean(j.enabled);state.snapshotMeta=j.snapshot?{id:j.snapshot.id,actor:j.snapshot.actor,created_at:j.snapshot.created_at}:null;state.snapshotHistory=j.history||[];refreshSelectors();}catch{}}
async function loadLatestSnapshot(apply=false){const s=$('#snapshotStatus');try{const r=await authFetch(`/api/snapshot?study=${encodeURIComponent(state.study)}`),j=await r.json();state.db=Boolean(j.enabled);if(!j.snapshot){if(s)s.textContent='No shared snapshot exists yet.';return;}state.snapshotMeta={id:j.snapshot.id,actor:j.snapshot.actor,created_at:j.snapshot.created_at};if(apply){const snap=j.snapshot.snapshot||{};state.selectRows=Array.isArray(snap.selectRows)?snap.selectRows:[];state.visitRows=Array.isArray(snap.visitRows)?snap.visitRows:[];state.sources=snap.sources||{};discover();state.patients=buildPatients(state.site,state.selectRows,state.visitRows,noteFor);renderPage();refreshSelectors();if(s)s.textContent=`Loaded snapshot from ${fmt(j.snapshot.created_at)}.`;}}catch(err){if(s)s.textContent=err?.message||'Could not load snapshot.';}}

async function importLabelFiles(files){if(!files.length)return;try{const all=[],sources=[];for(const file of files){const result=await importLabelFile(file);all.push(...result.ids);sources.push(result.source);}state.labels=[...new Set(all.map(x=>String(x).trim()).filter(Boolean))];state.labelSource=sources.join(', ');state.labelMeta.from=1;state.labelMeta.to='';renderPage();if(!state.labels.length){const s=$('#labelExportStatus');if(s)s.textContent='File loaded, but no label IDs were recognized.';}}catch(err){const s=$('#labelExportStatus');if(s)s.textContent=err?.message||'Could not import label file.';}finally{const p=$('#labelFilePicker');if(p)p.value='';}}
async function importReportFiles(files){if(!files.length)return;try{const result=await importReportFile(files[0]);state.report={...state.report,...result,visit:result.visit||state.report.visit||'',dates:result.dates||state.report.dates||'',site:result.site||state.report.site||state.site||'',monitor:result.monitor||state.report.monitor||''};renderPage();const s=$('#reportExportStatus');if(s)s.textContent=`Imported ${result.sourceType}: ${result.source}`;}catch(err){const s=$('#reportExportStatus');if(s)s.textContent=err?.message||'Could not import report file.';}finally{const p=$('#reportFilePicker');if(p)p.value='';}}

function annotationFromForm(ref){const [patient,visit]=ref.split('|');return {patient,visit:Number(visit),note:$(`[data-note="${ref}"]`)?.value||'',overrideDate:$(`[data-odate="${ref}"]`)?.value||'',overrideRegimen:$(`[data-oreg="${ref}"]`)?.value||'',deviationReason:$(`[data-devreason="${ref}"]`)?.value||'',deviationNo:$(`[data-devno="${ref}"]`)?.value||'',deviationStatus:$(`[data-devstatus="${ref}"]`)?.value||'',deviationOwner:$(`[data-devowner="${ref}"]`)?.value||''};}
async function saveNote(ref){const data=annotationFromForm(ref),k=noteKey(state.site,data.patient,data.visit),previous=state.notes[k]||{};state.localHistory[k]=[...(state.localHistory[k]||[]),previous].slice(-25);state.notes[k]={...data,updatedBy:state.user.name+(actorInitials()?` · ${actorInitials()}`:'')};saveLocal();state.patients=buildPatients(state.site,state.selectRows,state.visitRows,noteFor);renderPage();try{const r=await authFetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({study:state.study,site:state.site,...data,action:'Saved visit working data'})});if(r.ok)await syncWorkspace(false);}catch{}}
async function undoNote(ref){const [patient,visitRaw]=ref.split('|'),visit=Number(visitRaw),k=noteKey(state.site,patient,visit);if(state.db){try{const r=await authFetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({study:state.study,site:state.site,patient,visit,mode:'undo'})});if(r.ok){await syncWorkspace();return;}}catch{}}const hist=state.localHistory[k]||[];if(!hist.length)return;state.notes[k]=hist.pop()||{};state.localHistory[k]=hist;saveLocal();state.patients=buildPatients(state.site,state.selectRows,state.visitRows,noteFor);renderPage();}
async function showHistory(ref){const [patient,visitRaw]=ref.split('|'),visit=Number(visitRaw),panel=$(`[data-history-panel="${ref}"]`);if(!panel)return;panel.innerHTML='Loading history…';if(state.db){try{const r=await authFetch(`/api/workspace?study=${encodeURIComponent(state.study)}&site=${encodeURIComponent(state.site)}&patient=${encodeURIComponent(patient)}&visit=${visit}&history=1`),j=await r.json();if(r.ok){panel.innerHTML=(j.history||[]).map(h=>`<div><b>${fmt(h.created_at)}</b> · ${esc(h.actor||'—')}<small>${esc(JSON.stringify(h.payload||{}).slice(0,240))}</small></div>`).join('')||'<span>No previous versions.</span>';return;}}catch{}}const local=state.localHistory[noteKey(state.site,patient,visit)]||[];panel.innerHTML=local.slice().reverse().map((h,i)=>`<div><b>Local version ${local.length-i}</b><small>${esc(JSON.stringify(h).slice(0,240))}</small></div>`).join('')||'<span>No previous versions.</span>';}
async function syncWorkspace(rerender=true){if(state.study!=='CL04041383'||!state.site)return;try{const r=await authFetch(`/api/workspace?study=${encodeURIComponent(state.study)}&site=${encodeURIComponent(state.site)}`);if(!r.ok)return;const j=await r.json();state.db=Boolean(j.enabled);if(state.db){const prefix=`${state.study}|${state.site}|`;Object.keys(state.notes).filter(k=>k.startsWith(prefix)).forEach(k=>delete state.notes[k]);(j.annotations||[]).forEach(a=>state.notes[noteKey(a.site_id,a.patient_id,a.visit_no)]={note:a.note_text||'',overrideDate:a.override_date?String(a.override_date).slice(0,10):'',overrideRegimen:a.override_regimen||'',deviationReason:a.deviation_reason||'',deviationNo:a.deviation_no||'',deviationStatus:a.deviation_status||'',deviationOwner:a.deviation_owner||'',updatedBy:a.updated_by||'',updatedRole:a.updated_role||'',updatedAt:a.updated_at||''});}state.audit=j.audit||[];saveLocal();state.patients=buildPatients(state.site,state.selectRows,state.visitRows,noteFor);if(rerender)renderPage();}catch{}}

async function runLiveOperator(){const out=$('#aiPacket');if(!out)return;out.textContent='Loading shared operator data…';try{const summary=await authFetch('/api/operator?action=summary'),sj=await summary.json();if(!summary.ok)throw new Error(sj.error||'Operator summary failed');let payload={summary:sj};if(state.site){const ar=await authFetch(`/api/operator?action=actions&site=${encodeURIComponent(state.site)}`),aj=await ar.json();if(ar.ok)payload.currentSiteActions=aj;}out.textContent=JSON.stringify(payload,null,2);}catch(err){out.textContent=err?.message||'Shared operator check failed.';}}
function patientCsv(){const rows=[['Patient','Baseline','Status','Violations','W22 Actual','W22 Regimen','W40 Actual','W40 Regimen']];state.patients.forEach(p=>rows.push([p.id,p.baseline,p.status,p.violations,dateKey(p.visits[5]?.actual),p.visits[5]?.regimen||'',dateKey(p.visits[8]?.actual),p.visits[8]?.regimen||'']));return rows;}
function actionCsv(){const rows=[['Patient','Type','Detail']];actionItems().forEach(x=>rows.push([x.p,x.tone,x.sub]));return rows;}
function exportCSV(name,rows){const csv='\ufeff'+rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(';')).join('\r\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=name;a.click();URL.revokeObjectURL(a.href);}
function printLabels(){updateLabelMeta();const j=labelJob();if(!j.ids.length)return;const per=j.perLabel||1,base=Array.from({length:Math.ceil(j.ids.length/per)},(_,i)=>j.ids.slice(i*per,i*per+per)),groups=[];base.forEach(g=>{for(let c=0;c<Math.max(1,j.copies||1);c++)groups.push(g);});$('#printRoot').innerHTML=groups.map(g=>`<section class="print-label custom-print" style="width:${j.width}mm;height:${j.height}mm"><strong>CL04041109 · Placebo</strong><span>Batch ${esc(j.batch)} · Mfg ${esc(j.mfg)} · Exp ${esc(j.exp)}</span><div>${g.map(x=>`<b>${esc(x)}</b>`).join('')}</div><small>Только для клинических исследований</small></section>`).join('');document.body.classList.add('printing');setTimeout(()=>{window.print();document.body.classList.remove('printing');},60);}
function printReport(){updateReportState();const r=reportJob();$('#printRoot').innerHTML=`<article class="print-report"><h1>Interim Monitoring Visit Report</h1><p><b>Protocol:</b> CL04041383 &nbsp; <b>Site:</b> ${esc(r.site)}</p><p><b>IMV:</b> #${esc(r.visit)} &nbsp; <b>Dates:</b> ${esc(r.dates)}</p><p><b>Monitor:</b> ${esc(r.monitor||'—')}</p><hr><h2>Summary</h2><p>${esc(r.summary||'No summary entered.').replace(/\n/g,'<br>')}</p></article>`;document.body.classList.add('printing');setTimeout(()=>{window.print();document.body.classList.remove('printing');},60);}
function prepareAi(){const prompt=$('#aiPrompt')?.value.trim()||'',all=allSiteSummaries(),problems=[];all.forEach(s=>s.patientRows.forEach(p=>p.visits.forEach(v=>{const n=noteForSite(s.site,p.id,v.no),due=visitDueState(v);if(['Early','Late'].includes(v.window)||v.changed||due)problems.push({site:s.site,patient:p.id,visit:v.no,week:v.week,window:v.window,actual:dateKey(v.actual),range:[dateKey(v.min),dateKey(v.max)],before:v.before,regimen:v.regimen,changed:v.changed,due:due?.label||'',deviation:{no:n.deviationNo||'',reason:n.deviationReason||'',status:n.deviationStatus||'',owner:n.deviationOwner||''},note:n.note||''});})));$('#aiPacket').textContent=JSON.stringify({task:prompt||'Review current workspace',study:state.study,rules:['Imported exports are source-of-truth','Shared snapshots are explicitly published processed copies','Manual corrections are working overrides','Week 22/V6 and Week 40/V9 are regimen checkpoints','Do not invent deviation reasons/numbers'],summary:{sites:all.length,patients:all.reduce((a,x)=>a+x.patients,0),windowExceptions:all.reduce((a,x)=>a+x.exceptions,0),dueSoon:all.reduce((a,x)=>a+x.dueSoon,0),overdue:all.reduce((a,x)=>a+x.overdue,0)},problems},null,2);}
function empty(t){return `<div class="empty">${esc(t)}</div>`;}
boot();
